import{_ as t,c as e,a2 as a,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百七十四章 最终带来痛苦","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/274第二百七十四章 最终带来痛苦.md","filePath":"meditation/巴利文大藏经/274第二百七十四章 最终带来痛苦.md"}'),r={name:"meditation/巴利文大藏经/274第二百七十四章 最终带来痛苦.md"};function _(n,p,i,s,d,c){return o(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百七十四章-最终带来痛苦" tabindex="-1">第二百七十四章 最终带来痛苦 <a class="header-anchor" href="#第二百七十四章-最终带来痛苦" aria-label="Permalink to &quot;第二百七十四章 最终带来痛苦&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应67经/苦经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，一位比丘（出家人），来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，这位比丘对佛陀说：“世尊，请您教导给我一个简要的修行方法，让我独自修行的时候，能够管束好自己的行为、言语、念想，让我不放逸自己的行为、言语、念想肆意妄为、胡作非为，让我不胡思乱想，能长久的安住在清净的境界之中，让我能够精进努力的去修行，世尊，如果您教导给我的正法能够让我这样的话，那就很好了。”</p><p>佛陀说：“比丘！对于那些最终带来痛苦的事物，你不应该对它们生起欲望、渴爱。”</p><p>这位比丘对佛陀说：“世尊，我已经明白您所说的法义了。”</p><p>佛陀说：“比丘！你既然明白了如来所说的法义，那么你现在就在如来面前详细的讲说这个法义吧。”</p><p>这位比丘说：“世尊，物质事物、物质身体、感受、念想、行为、认识、分别、判断最终带来的是痛苦。</p><p>物质事物、物质身体最终带来的是痛苦，为什么这么说呢？因为就算物质事物、物质身体带来了快乐，那都是短暂的。世间一切的物质事物、物质身体随时都在变化，无法永远的存在，无法永恒的保持不变，无法永远的拥有，当失去这些物质事物的时候，当这些物质事物衰败、灭亡、消失的时候，当物质身体生病、衰老、临死的时候，就会带来痛苦，之前这些物质事物、物质身体带来了多少的快乐，当失去这些物质事物的时候，当这些物质事物衰败、灭亡、消失的时候，当物质身体生病、衰老、临死的时候，就会带来多少痛苦，所以世间的物质事物、物质身体带来的最终都是痛苦。</p><p>感受、念想、行为、认识、分别、判断最终带来的是痛苦，为什么这么说呢？因为就算感受、念想、行为、认识、分别、判断带来了快乐，那都是短暂的。世间一切的感受、念想、行为、认识、分别、判断随时都在变化，无法永远的存在，无法永恒的保持不变，无法永远的拥有，当失去这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断的时候，当这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断消退、灭尽、消失的时候，当感受、念想、行为、认识、分别、判断让世间人、众生不满意、不开心、不快乐的时候，就会带来痛苦，之前这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断带来了多少的快乐，当失去这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断的时候，当这些让世间人、众生满意、开心、快乐的感受、念想、行为、认识、分别、判断消退、灭尽、消失的时候，当感受、念想、行为、认识、分别、判断让世间人、众生不满意、不开心、不快乐的时候，就会带来多少痛苦，所以世间的感受、念想、行为、认识、分别、判断带来的最终都是痛苦。</p><p>因此，不应该对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起欲望、渴爱，应该除灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断的欲望、渴爱。”</p><p>佛陀说：“比丘！很好！很好！你已经完全明白如来刚才所说的法义了，你就应该这样去修行。”</p><p>佛陀说法后，这位出家人再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他站起来向右围绕着佛陀转圈，以此表示他对佛陀的最高敬意，之后他就离开了。</p><p>这位出家人，他按着佛陀所说的正法独自的去修行，他管束好了自己的行为、言语、念想，不让自己胡思乱想、胡作非为，他让自己的内心安住在清净的境界之中，没有过多久，这位出家人他就开启了解脱的智慧，他就证悟了解脱的果位，他自己彻底明白：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生在世间了，已经彻底从生死轮回中解脱出来。」</p><p>这位出家人成为了佛陀阿罗汉弟子中的一员。</p>',15)]))}const f=t(r,[["render",_]]);export{m as __pageData,f as default};
